import argparse,json,sys
from pathlib import Path
sys.path.insert(0,'scripts');import inspection
out=Path('artifacts/webtransport')
orders=[['empty-packet-tree','quic-recordless-vendor-control','quic-recordless'],['quic-recordless-vendor-control','quic-recordless','empty-packet-tree'],['quic-recordless','empty-packet-tree','quic-recordless-vendor-control']]
for repeat,variants in enumerate(orders,1):
 for case in ['private','roomonly','mixed']:
  for variant in variants:
   a=json.loads((out/f'owner-poll-{case}-owner-poll-1.json').read_text())['args'];a.update(server=str((out/f'binaries/{variant}-relay').resolve()),output=str((out/f'quic-recordless-three-{case}-{variant}-{repeat}.json').resolve()))
   for k in ['server','client','client_source_root','tls_front','tls_cert','tls_key','tls_ca','heap_profile','heap_library','output','fanout_latency_output']:
    if a.get(k) is not None:a[k]=Path(a[k])
   if a['output'].exists():
    saved=json.loads(a['output'].read_text())
    expected={k:str(v) if isinstance(v,Path) else v for k,v in a.items()}
    assert saved['passed'] and saved['server_sha256']==inspection.digest(a['server']) and saved['client_sha256']==inspection.digest(a['client']) and saved['args']==expected, a['output']
    print('VERIFIED EXISTING',case,variant,repeat,flush=True)
    continue
   result=inspection.run(argparse.Namespace(**a));assert result['passed'],a['output'];print('COMPARED',case,variant,repeat,flush=True)

